mapper.select:
SELECT EXISTS (
	SELECT 1 FROM customer
	WHERE email = #{email} AND deleted_yn = 'N'
	AND customer_id <> #{excludeId}
)

sql.where:
deleted_yn = 'N'

	AND (name ILIKE #{s.keywordName} OR email LIKE #{s.keywordEmail}
	OR phone LIKE #{s.keywordPhone})

AND region_code = #{s.regionCode}
AND email_consent_yn = #{s.emailConsent}
AND sms_consent_yn = #{s.smsConsent}
AND dormant_yn = #{s.dormant}

mapper.select:
SELECT EXISTS (
	SELECT 1 FROM customer c
	WHERE c.customer_id = #{customerId} 
)

SELECT c.customer_id FROM customer c
WHERE c.customer_id IN
#{id}

SELECT c.customer_id FROM customer c
WHERE c.customer_id > #{afterId} 


		AND c.email IS NOT NULL
		AND GREATEST(c.email_consent_at, ) <= now() - INTERVAL '2 years'


		AND GREATEST(c.sms_consent_at, ) <= now() - INTERVAL '2 years'


  AND NOT EXISTS (SELECT 1 FROM send_log s
                  WHERE s.customer_id = c.customer_id AND s.kind = 'NOTICE' AND s.channel = #{channel}
                    AND (s.status IN ('PENDING', 'SENDING') OR s.created_at > now() - INTERVAL '30 days'))
ORDER BY c.customer_id
LIMIT #{limit}

mapper.sql:
(SELECT max(s.sent_at) FROM send_log s
 WHERE s.customer_id = c.customer_id AND s.kind = 'NOTICE' AND s.channel = #{channel}
   AND s.status IN ('SENT', 'BOUNCED'))

mapper.select:
SELECT history_id, channel, before_yn, after_yn, source, note, changed_at
FROM consent_history WHERE customer_id = #{customerId}
ORDER BY changed_at DESC, history_id DESC
